"use client";
import { useEffect, useRef, type ComponentProps } from "react";
import { StepButton } from "./button";
import { Icon } from "./icon";
import { cn } from "./cn";
import { haptic } from "./haptics";

export interface StepperProps extends Omit<ComponentProps<"div">, "onChange" | "children" | "role" | "aria-label"> {
  value: number;
  onChange: (next: number) => void;
  min: number;
  max: number;
  step?: number;
  /** Shown after the number, e.g. "backups" or "h". */
  unit?: string;
  /** Names the control for screen readers, e.g. "Backups to keep". */
  label: string;
}

const HOLD_DELAY = 420;
const SCRUB_PX = 14; // how far to drag the number for one step

/**
 * A number you nudge up and down with round buttons, held between `min` and `max`. Tap for one step. Press and hold to run through a
 * range: it starts steady and speeds up the longer you hold. Or drag the number itself sideways, one step every few pixels, like
 * scrubbing. Each step ticks, and reaching either end bumps. Arrow keys work too. For small counts, not free typing.
 */
export function Stepper({ value, onChange, min, max, step = 1, unit, label, className, onKeyDown, ...rest }: StepperProps) {
  const now = useRef(value);
  useEffect(() => { now.current = value; }, [value]);
  const timers = useRef<{ wait?: ReturnType<typeof setTimeout>; loop?: ReturnType<typeof setTimeout>; held: boolean }>({ held: false });
  const scrub = useRef<{ id: number; x: number; base: number; hit: boolean } | null>(null);

  /** One step. Returns false at the end of the range, with a bump instead of a tick. */
  const move = (dir: 1 | -1, kind: "light" | "tick" = "light") => {
    const next = Math.min(max, Math.max(min, now.current + dir * step));
    if (next === now.current) { haptic("boundary"); return false; }
    haptic(kind); now.current = next; onChange(next);
    return true;
  };
  const stop = () => { clearTimeout(timers.current.wait); clearTimeout(timers.current.loop); };
  const start = (dir: 1 | -1) => {
    timers.current.held = false; stop();
    timers.current.wait = setTimeout(() => {
      timers.current.held = true;
      let n = 0;
      const run = () => { if (!move(dir, "tick")) return; n++; timers.current.loop = setTimeout(run, Math.max(35, 130 - n * 8)); }; // faster the longer it is held
      run();
    }, HOLD_DELAY);
  };
  const tap = (dir: 1 | -1) => { if (timers.current.held) { timers.current.held = false; return; } move(dir); };

  const dragDown = (e: React.PointerEvent<HTMLOutputElement>) => { scrub.current = { id: e.pointerId, x: e.clientX, base: now.current, hit: false }; try { e.currentTarget.setPointerCapture(e.pointerId); } catch { /* still scrubs inside the number */ } };
  const dragMove = (e: React.PointerEvent<HTMLOutputElement>) => {
    const s = scrub.current; if (!s || e.pointerId !== s.id) return;
    const steps = Math.trunc((e.clientX - s.x) / SCRUB_PX);
    const raw = s.base + steps * step, target = Math.min(max, Math.max(min, raw));
    if (target !== now.current) { haptic("tick"); now.current = target; onChange(target); }
    if (raw !== target && !s.hit) { s.hit = true; haptic("boundary"); } else if (raw === target) s.hit = false;
  };
  return (
    <div data-slot="stepper" role="group" aria-label={label} className={cn("stepper", className)} {...rest}
      onKeyDown={(e) => { onKeyDown?.(e); if (e.defaultPrevented) return; if (e.key === "ArrowUp" || e.key === "ArrowRight") { e.preventDefault(); move(1); } else if (e.key === "ArrowDown" || e.key === "ArrowLeft") { e.preventDefault(); move(-1); } }}>
      <StepButton aria-label={`Fewer: ${label}`} disabled={value <= min} onPointerDown={() => start(-1)} onPointerUp={stop} onPointerLeave={stop} onPointerCancel={stop} onClick={() => tap(-1)}><Icon n="minus" /></StepButton>
      <output className="stepper-v num" aria-live="polite" title="Drag sideways to change" onPointerDown={dragDown} onPointerMove={dragMove} onPointerUp={() => { scrub.current = null; }} onPointerCancel={() => { scrub.current = null; }}>{value}{unit ? <small> {unit}</small> : null}</output>
      <StepButton aria-label={`More: ${label}`} disabled={value >= max} onPointerDown={() => start(1)} onPointerUp={stop} onPointerLeave={stop} onPointerCancel={stop} onClick={() => tap(1)}><Icon n="plus" /></StepButton>
    </div>
  );
}

import type { ComponentProps } from "react";
import { cva } from "class-variance-authority";
import { cn } from "./cn";
import { Icon } from "./icon";
import { haptic as play, type Haptic } from "./haptics";

/** Class recipe for anything that should look like a button (links, triggers). */
export const buttonVariants = cva("btn", {
  variants: {
    variant: { default: "", primary: "btn--p", sage: "btn--sage", danger: "btn--danger", ghost: "btn--ghost" },
    size: { sm: "btn--sm", md: "", lg: "btn--lg" },
  },
  defaultVariants: { variant: "default", size: "md" },
});

export type ButtonVariant = NonNullable<ButtonProps["variant"]>;
export type ButtonProps = ComponentProps<"button"> & {
  /** `primary` is the one main action on a surface (dark); `sage` confirms calmly; `danger` is for things that cannot be undone; `ghost` is borderless; the default is a quiet fill. */
  variant?: "default" | "primary" | "sage" | "danger" | "ghost";
  /** `md` is 42 px tall; `lg` is 52 px (thumb-sized, for the main action on a phone); `sm` is for dense rows. */
  size?: "sm" | "md" | "lg";
  /** Shows a spinner, keeps the width, and ignores taps until it clears. */
  loading?: boolean;
  /** A haptic on press. Off by default: a plain tap needs none. Use `medium` for the one action that sends something out, `warning` for a danger button. */
  haptic?: Haptic;
};

/** Pill-shaped action button. Icons and text go in as children. Ref and native props pass through. */
export function Button({ variant, size, className, type = "button", loading, children, disabled, haptic, onClick, ...rest }: ButtonProps) {
  return (
    <button data-slot="button" data-variant={variant ?? "default"} data-loading={loading ? "" : undefined} aria-busy={loading || undefined} type={type}
      className={cn(buttonVariants({ variant, size }), className)} disabled={disabled || loading} onClick={(e) => { if (haptic) play(haptic); onClick?.(e); }} {...rest}>
      {loading ? <Icon n="refresh" c="sm spin" /> : null}{children}
    </button>
  );
}

/** Square, icon-only button. It has no visible text, so it must carry an accessible name. */
export function IconButton({ active, className, type = "button", haptic, onClick, ...rest }: Omit<ComponentProps<"button">, "aria-label"> & {
  /** Names the button for screen readers. Required: there is no text to read. */
  "aria-label": string;
  /** Marks it as the current choice (a pressed look). */
  active?: boolean;
  /** A haptic on press. Off by default. */
  haptic?: Haptic;
}) {
  return <button data-slot="icon-button" data-active={active ? "" : undefined} type={type} className={cn("icon-btn", active && "on", className)} onClick={(e) => { if (haptic) play(haptic); onClick?.(e); }} {...rest} />;
}

/** Round stepper button (plus or minus). Like `IconButton`, it needs an accessible name. */
export function StepButton({ className, type = "button", haptic, onClick, ...rest }: Omit<ComponentProps<"button">, "aria-label"> & {
  /** Names the button for screen readers: "More backups". */
  "aria-label": string;
  /** A haptic on press. Off by default: a `Stepper` ticks for itself. */
  haptic?: Haptic;
}) {
  return <button data-slot="step-button" type={type} className={cn("step-btn", className)} onClick={(e) => { if (haptic) play(haptic); onClick?.(e); }} {...rest} />;
}

/* Buttons: Button, IconButton, StepButton. Moved out of globals.css; contextual overrides (.hero .btn, .pg3 .dt) stay with the screens that need them. */
.btn{display:inline-flex;align-items:center;justify-content:center;gap:8px;min-height:42px;padding:0 18px;border-radius:99px;font-weight:600;font-size:0.875rem;background:var(--tile2);color:var(--ink);transition:transform .12s,filter .2s;white-space:nowrap}
@media(hover:hover){
  .btn:hover{filter:brightness(.97)}
}
.btn--p{background:var(--ink);color:var(--tile)}
.btn--sage{background:var(--sage);color:var(--on-sage)}
.btn--sm{min-height:34px;padding:0 13px;font-size:0.8125rem}
.btn--danger{background:var(--crit);color:var(--on-crit)}
.btn[disabled]{opacity:.45;cursor:not-allowed}
.icon-btn{width:36px;height:36px;border-radius:12px;display:grid;place-items:center;color:var(--ink2);flex:none}
@media(hover:hover){
  .icon-btn:hover{background:var(--tile2)}
}
.icon-btn.on{color:var(--glow-ink)}
.icon-btn.on .ic{fill:var(--glow)}
.step-btn{width:42px;height:42px;border-radius:50%;background:var(--over);display:grid;place-items:center}
.btn--ghost{background:transparent}
.btn--lg{min-height:50px;padding:0 24px;font-size:0.9375rem}
.btn[data-loading]{cursor:progress;opacity:1}
.btn[data-loading][disabled]{opacity:.85}
